const items = [];

function parseRss(xmlText, category, source) {
  if (!xmlText || typeof xmlText !== 'string') return;
  const itemMatches = xmlText.matchAll(/<item>([\s\S]*?)<\/item>/gi);
  for (const match of itemMatches) {
    const itemXml = match[1];
    const titleMatch = itemXml.match(/<title>([\s\S]*?)<\/title>/i);
    const linkMatch = itemXml.match(/<link>([\s\S]*?)<\/link>/i);
    const descMatch = itemXml.match(/<description>([\s\S]*?)<\/description>/i);

    if (titleMatch && linkMatch) {
      const rawTitle = titleMatch[1].replace(/<!\[CDATA\[(.*?)\]\]>/gi, '$1').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'").trim();
      const rawLink = linkMatch[1].replace(/<!\[CDATA\[(.*?)\]\]>/gi, '$1').trim();
      let rawDesc = descMatch ? descMatch[1].replace(/<[^>]*>?/gm, '').replace(/<!\[CDATA\[(.*?)\]\]>/gi, '$1').trim() : rawTitle;

      items.push({
        source,
        source_id: rawLink.slice(-32),
        title: rawTitle,
        content: rawDesc,
        url: rawLink,
        category,
        score: 100
      });
    }
  }
}

try {
  const indo = $('Fetch Google News Indo Celeb').first().json.data;
  parseRss(indo, 'seleb-lokal', 'google-news-indo');
} catch (e) {}

try {
  const soompi = $('Fetch Soompi K-Pop Feeds').first().json.data;
  parseRss(soompi, 'kpop-asia', 'soompi');
} catch (e) {}

try {
  const hollywood = $('Fetch Google News Hollywood').first().json.data;
  parseRss(hollywood, 'hollywood-barat', 'google-news-hollywood');
} catch (e) {}

// Safety Pre-Filter & Anti-Duplication Signature
const forbidden = ['bunuh diri', 'porn', 'bokep', 'telanjang', 'gore', 'mutilasi', 'pedofil'];
const safeItems = items.filter(item => {
  const lower = (item.title + ' ' + item.content).toLowerCase();
  return !forbidden.some(word => lower.includes(word));
});

// Add Entity-Event Signature
safeItems.forEach(item => {
  const cleanTitle = item.title.toLowerCase().replace(/[^a-z0-9]/g, '');
  item.event_signature = cleanTitle.slice(0, 32);
});

// Ambil maksimal 2 item per run agar DeepSeek v4 tidak overload
return safeItems.slice(0, 2).map(item => ({ json: item }));
